class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def delete_min(head):
    if head is None:
        return None
    min_node = head
    min_prev = None
    prev = None
    node = head
    while node is not None:
        if node.val < min_node.val:
            min_node = node
            min_prev = prev
        prev = node
        node = node.next
    if min_prev is None:
        return head.next
    min_prev.next = min_node.next
    return head

def build(values):
    head = None
    for v in reversed(values):
        head = Node(v, head)
    return head

def values_of(head):
    out = []
    while head is not None:
        out.append(head.val)
        head = head.next
    return out

print(values_of(delete_min(build([3, 1, 2]))))
print(delete_min(None))
print(values_of(delete_min(build([7]))))
print(values_of(delete_min(build([1, 2, 3]))))

